'use strict';

/* Terreno dos mapas.
 *
 * A textura pintada de cada mapa e desenhada sob a grade. Ela passa por um
 * ajuste antes de entrar aqui: escurecida para brilho medio 20 e com o
 * contraste interno comprimido para desvio 7, alem de dessaturada a 40%.
 *
 * Isso nao e gosto, e medida. Os inimigos aparecem com 24 a 58px, e o mais
 * escuro deles (o Chefe) tem brilho 59. Com a textura crua, brilho 53 e
 * desvio 18, ele se separava do chao por apenas 1,2 vezes o ruido do proprio
 * fundo -- ou seja, sumia. Depois do ajuste sao cerca de 5,5 vezes, e o
 * Veloz, que e o menor, passa de 11.
 *
 * Trocar BRILHO e DESVIO no script de processamento e o unico botao: menos
 * desvio deixa o chao mais liso e o inimigo mais visivel; mais desvio faz o
 * caminho inverso.
 */

const TERRENOS = {
  planicie: 'data:image/jpeg;base64,',
  desfiladeiro: 'data:image/jpeg;base64,',
  ruinas: 'data:image/jpeg;base64,'
};

const Terrain = {
  load() {
    this.imgs = {};
    for (const key of Object.keys(TERRENOS)) {
      const img = new Image();
      img.onload = () => { img.pronta = true; };
      img.src = TERRENOS[key];
      this.imgs[key] = img;
    }
  },

  /* Devolve a textura so quando ela chegou; ate la o chao antigo continua
   * valendo, entao nada pisca no primeiro quadro. */
  get(mapId) {
    const img = this.imgs && this.imgs[mapId];
    return img && img.pronta ? img : null;
  }
};
